// CertStore.h - TLS root-CA trust anchors for the Yahoo client, with a field-updatable
// custom bundle. Two sources, in priority order:
//   1. /ca/bundle.pem on LittleFS  - uploaded over the authenticated web API, only ever
//      activated after a LIVE test fetch to Yahoo verifies the new roots (a failed or
//      power-cut install can never activate; same tmp->rename discipline as the ledger).
//   2. CA_BUNDLE in PROGMEM        - built-in roots, regenerated by tools/fetch_roots.py.
// There is deliberately NO insecure path: verification cannot be turned off.
#pragma once
#include <Arduino.h>
#include "../core/JsonWriter.h"

namespace certs {

bool pemSane(const char *pem, size_t len);        // pure: >=1 cert block, base64 body, <= CERT_PEM_MAX
uint8_t pemCount(const char *pem);                // pure: number of BEGIN CERTIFICATE markers
uint32_t pemHash(const char *pem, size_t len);    // pure: FNV-1a, for status/idle display

// Device side. active() returns the PEM to feed setCACert() (PROGMEM builtin or a one-time
// heap copy of the custom file; the copy is cached and invalidated on install/reset).
const char *active();
const char *sourceName();                         // "builtin" | "custom"
bool installNew(const char *pem, size_t len, char *err, size_t errN);  // validate + live-verify + atomic activate
bool resetToBuiltin(char *err, size_t errN);
bool bootSweep();                         // drop an orphan /ca/bundle.new left by a power cut (call after storage::begin)
void statusJson(JsonWriter &w);                   // {"certs":{"source":..,"roots":n,"hash":..,"custom":bool}}
}
